import React from "react";
import { motion } from "framer-motion";
import { COLLECTIONS } from "./Content";
import { Sparkles } from "lucide-react";

export default function Collections({ onOpenQuote }) {
  return (
    <section id="collections" className="section" style={{ background: "#fff" }}>
      <div className="container mx-auto">
        {/* Section Header */}
        <motion.div
          className="mb-12 lg:mb-16 text-center"
          initial={{ opacity: 0, y: 20 }}
          whileInView={{ opacity: 1, y: 0 }}
          viewport={{ once: true }}
          transition={{ duration: 0.7 }}
        >
          <div className="flex items-center justify-center gap-3 mb-6">
            <div className="w-10 h-px" style={{ background: "linear-gradient(90deg, transparent, #d4af37)" }} />
            <span className="overline">Our Collections</span>
            <div className="w-10 h-px" style={{ background: "linear-gradient(90deg, #d4af37, transparent)" }} />
          </div>
          <h2 className="section-title">
            Six fabric series for every kind of{" "}
            <span>celebration</span>.
          </h2>
          <p className="section-subtitle mt-6 mx-auto text-center">
            Hand-picked, trend-driven and ready in bulk — discover the fabrics decorators across India keep coming back for.
          </p>
        </motion.div>

        {/* Collections Grid - Desktop Optimized */}
        <div className="collections-grid">
          {COLLECTIONS.map((item, i) => (
            <motion.a
              key={item.id}
              href="#contact"
              className="collection-card group"
              initial={{ opacity: 0, y: 30 }}
              whileInView={{ opacity: 1, y: 0 }}
              viewport={{ once: true }}
              transition={{ delay: i * 0.08, duration: 0.6 }}
              whileHover={{ scale: 1.03 }}
            >
              <img
                src={item.image}
                alt={item.title}
                loading="lazy"
                onError={(e) => {
                  e.target.src = `https://images.unsplash.com/photo-1519167758481-83f550bb49b3?w=800&auto=format&fit=crop`;
                }}
              />
              {/* Gradient overlay */}
              <div className="absolute inset-0" style={{ background: "linear-gradient(180deg, transparent 40%, rgba(26,8,10,0.9) 100%)" }} />
              {/* Content */}
              <div className="collection-card-overlay">
                <span className="collection-card-overline">{item.overline}</span>
                <h3 className="collection-card-title">{item.title}</h3>
                <p className="text-sm mt-2 hidden sm:block" style={{ color: "rgba(255,255,255,0.8)", lineHeight: 1.5 }}>
                  {item.desc}
                </p>
              </div>
            </motion.a>
          ))}
        </div>

        {/* CTA */}
        <motion.div
          className="text-center mt-12 lg:mt-16"
          initial={{ opacity: 0, y: 20 }}
          whileInView={{ opacity: 1, y: 0 }}
          viewport={{ once: true }}
          transition={{ duration: 0.7 }}
        >
          <button onClick={onOpenQuote} className="btn-primary">
            <Sparkles size={18} />
            <span>Request a Custom Quote</span>
          </button>
        </motion.div>
      </div>
    </section>
  );
}
